# Excel to CSV Converter using Qt5

Here's a complete C++ Qt5 application that converts Excel files to CSV format. Since Qt doesn't have built-in Excel support, I'll use **QAxObject** (Windows/COM) approach, which is the most reliable for handling `.xls` and `.xlsx` files.

## main.cpp

```cpp
#include <QApplication>
#include <QWidget>
#include <QVBoxLayout>
#include <QHBoxLayout>
#include <QPushButton>
#include <QLabel>
#include <QLineEdit>
#include <QFileDialog>
#include <QMessageBox>
#include <QDir>
#include <QFileInfo>
#include <QProgressBar>
#include <QTextEdit>
#include <QAxObject>
#include <QDateTime>

class ExcelConverter : public QWidget {
    Q_OBJECT

public:
    ExcelConverter(QWidget *parent = nullptr) : QWidget(parent) {
        setupUI();
        setWindowTitle("Excel to CSV Converter");
        resize(600, 400);
    }

private slots:
    void browseFolder() {
        QString dir = QFileDialog::getExistingDirectory(
            this, "Select Directory Containing Excel Files",
            QDir::homePath(),
            QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks);

        if (!dir.isEmpty()) {
            pathEdit->setText(dir);
        }
    }

    void convertFiles() {
        QString dirPath = pathEdit->text();
        if (dirPath.isEmpty()) {
            QMessageBox::warning(this, "Warning", "Please select a directory first.");
            return;
        }

        QDir dir(dirPath);
        if (!dir.exists()) {
            QMessageBox::critical(this, "Error", "Selected directory does not exist.");
            return;
        }

        // Find all Excel files
        QStringList filters;
        filters << "*.xlsx" << "*.xls" << "*.xlsm";
        QFileInfoList excelFiles = dir.entryInfoList(filters, QDir::Files);

        if (excelFiles.isEmpty()) {
            QMessageBox::information(this, "No Files", "No Excel files found in the selected directory.");
            return;
        }

        // Create output folder
        QString outputFolderName = "CSV_Output_" +
            QDateTime::currentDateTime().toString("yyyyMMdd_hhmmss");
        QString outputPath = dir.absoluteFilePath(outputFolderName);

        if (!dir.mkdir(outputFolderName)) {
            QMessageBox::critical(this, "Error", "Failed to create output folder.");
            return;
        }

        logArea->append("Output folder: " + outputPath);
        logArea->append("Found " + QString::number(excelFiles.size()) + " Excel file(s)\n");

        // Initialize Excel via COM
        QAxObject *excel = new QAxObject("Excel.Application", this);
        if (excel->isNull()) {
            QMessageBox::critical(this, "Error",
                "Failed to initialize Excel. Make sure Microsoft Excel is installed.");
            delete excel;
            return;
        }

        excel->setProperty("Visible", false);
        excel->setProperty("DisplayAlerts", false);

        QAxObject *workbooks = excel->querySubObject("Workbooks");

        progressBar->setMaximum(excelFiles.size());
        progressBar->setValue(0);

        int successCount = 0;
        int failCount = 0;

        for (int i = 0; i < excelFiles.size(); ++i) {
            const QFileInfo &fileInfo = excelFiles[i];
            QString filePath = QDir::toNativeSeparators(fileInfo.absoluteFilePath());

            logArea->append("Processing: " + fileInfo.fileName());
            QApplication::processEvents();

            QAxObject *workbook = workbooks->querySubObject(
                "Open(const QString&)", filePath);

            if (!workbook || workbook->isNull()) {
                logArea->append("  ERROR: Could not open file");
                failCount++;
                progressBar->setValue(i + 1);
                continue;
            }

            QAxObject *sheets = workbook->querySubObject("Worksheets");
            int sheetCount = sheets->property("Count").toInt();

            for (int s = 1; s <= sheetCount; ++s) {
                QAxObject *sheet = sheets->querySubObject("Item(int)", s);
                QString sheetName = sheet->property("Name").toString();

                // Build output filename
                QString baseName = fileInfo.completeBaseName();
                QString csvName;
                if (sheetCount > 1) {
                    csvName = QString("%1_%2.csv").arg(baseName, sheetName);
                } else {
                    csvName = QString("%1.csv").arg(baseName);
                }

                // Sanitize filename
                csvName.replace(QRegExp("[\\\\/:*?\"<>|]"), "_");

                QString csvPath = QDir::toNativeSeparators(
                    QDir(outputPath).absoluteFilePath(csvName));

                // Activate this sheet then save as CSV
                sheet->dynamicCall("Activate()");

                // 6 = xlCSV format
                workbook->dynamicCall("SaveAs(const QString&, int)", csvPath, 6);

                logArea->append("  -> Saved: " + csvName);
                delete sheet;
            }

            workbook->dynamicCall("Close(bool)", false);
            delete sheets;
            delete workbook;

            successCount++;
            progressBar->setValue(i + 1);
            QApplication::processEvents();
        }

        excel->dynamicCall("Quit()");
        delete workbooks;
        delete excel;

        logArea->append("\n=== Conversion Complete ===");
        logArea->append(QString("Success: %1 | Failed: %2").arg(successCount).arg(failCount));

        QMessageBox::information(this, "Done",
            QString("Conversion complete!\nSuccess: %1\nFailed: %2\n\nOutput: %3")
                .arg(successCount).arg(failCount).arg(outputPath));
    }

private:
    QLineEdit *pathEdit;
    QTextEdit *logArea;
    QProgressBar *progressBar;

    void setupUI() {
        QVBoxLayout *mainLayout = new QVBoxLayout(this);

        QLabel *titleLabel = new QLabel("<h2>Excel to CSV Converter</h2>");
        titleLabel->setAlignment(Qt::AlignCenter);
        mainLayout->addWidget(titleLabel);

        // Folder selection row
        QHBoxLayout *pathLayout = new QHBoxLayout();
        pathLayout->addWidget(new QLabel("Directory:"));
        pathEdit = new QLineEdit();
        pathEdit->setPlaceholderText("Select a folder containing Excel files...");
        pathLayout->addWidget(pathEdit);

        QPushButton *browseBtn = new QPushButton("Browse...");
        connect(browseBtn, &QPushButton::clicked, this, &ExcelConverter::browseFolder);
        pathLayout->addWidget(browseBtn);
        mainLayout->addLayout(pathLayout);

        // Convert button
        QPushButton *convertBtn = new QPushButton("Convert Excel Files to CSV");
        convertBtn->setStyleSheet("padding: 8px; font-weight: bold;");
        connect(convertBtn, &QPushButton::clicked, this, &ExcelConverter::convertFiles);
        mainLayout->addWidget(convertBtn);

        // Progress bar
        progressBar = new QProgressBar();
        progressBar->setValue(0);
        mainLayout->addWidget(progressBar);

        // Log area
        mainLayout->addWidget(new QLabel("Log:"));
        logArea = new QTextEdit();
        logArea->setReadOnly(true);
        mainLayout->addWidget(logArea);
    }
};

#include "main.moc"

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);
    ExcelConverter window;
    window.show();
    return app.exec();
}
```

## ExcelToCsv.pro (qmake project file)

```pro
QT += core gui widgets axcontainer

CONFIG += c++11

TARGET = ExcelToCsv
TEMPLATE = app

SOURCES += main.cpp
```

## How to Build and Run

1. **Save the files**: Save `main.cpp` and `ExcelToCsv.pro` in the same folder.
2. **Open in Qt Creator** (or use command line):
   ```bash
   qmake
   make            # or 'nmake' / 'jom' on Windows
   ```
3. **Run the executable**.

## Important Notes

- **Platform**: This solution uses `QAxObject` (COM automation), which means it **only works on Windows** and **requires Microsoft Excel to be installed**.
- **Multi-sheet workbooks**: If a workbook has multiple sheets, each sheet is saved as a separate CSV with the sheet name appended.
- **Output folder**: A timestamped folder like `CSV_Output_20240115_143022` is created inside the selected directory.

## Cross-Platform Alternative

If you need a cross-platform solution (Linux/macOS), you'd need a third-party library like:
- **libxlsxwriter** / **xlnt** for `.xlsx` files
- **QtXlsx** (a Qt module for Excel files)

Let me know if you'd like me to rewrite this using one of those libraries instead!

